--region 协议请求
function FurnitureInteractionMgr:ReqFurnitureFoodEat(InFurnitureID)
    --需要先检查下剩余次数，有可能其他人使用过了
    local FurnitureInfo = _G.HousingMgr:GetFurnitureInfo(InFurnitureID)
    if not FurnitureInfo then
        return
    end

    local ResID = FurnitureInfo.Key or 0
    local Cfg = HousingFurnitureCfg:FindCfgByKey(ResID)
    if not Cfg then
        return
    end

    if FurnitureInfo.Attr and FurnitureInfo.Attr.Food then
        local LeftTime = (Cfg.FuncParam[1] or 0) - (FurnitureInfo.Attr.Food.EatedTimes or 0)
        if LeftTime <= 0 then
            local ItemID = Cfg.ItemID
            local Name = ItemCfg:GetItemName(ItemID)
            MsgTipsUtil.ShowTips(string.format(HouseLocalDef.FurnitureInteractionFood.Tips3, Name))
            return
        end
    end
    
    local HouseID = _G.HousingMgr:GetIndoorHouseID()
    if HouseID <= 0 then
        HouseID = _G.HousingMgr.HouseID
    end
    local MsgID = CS_CMD.CS_CMD_FURNITURE_INTERACTION
    local SubMsgID = SUB_MSG_FURNITURE_ID.CS_SUBMSGID_FURNITURE_INTERACTION_FOOD_EAT
    local MsgBody = {}
    MsgBody.SubCmd = SubMsgID
    MsgBody.FootEat = {}
    MsgBody.FootEat.HouseID = HouseID
    MsgBody.FootEat.Region = _G.HousingMgr.Region
    MsgBody.FootEat.FurnitureID = InFurnitureID
    GameNetworkMgr:SendMsg(MsgID, SubMsgID, MsgBody,0, HouseID)
end

