--region 协议回包
function FurnitureInteractionMgr:RspFurnitureFoodEat(MsgBody)
    if not MsgBody then
        return
    end
    
    local FootEat = MsgBody.FootEat
    if not FootEat then
        return
    end
    
    local FurnitureID = FootEat.FurnitureID
    local EatedTimes = FootEat.EatedTimes
    local FurnitureInfo = _G.HousingMgr:GetFurnitureInfo(FurnitureID)
    if not FurnitureInfo then
        return
    end
    
    local ResID = FurnitureInfo.Key or 0
    local Cfg = HousingFurnitureCfg:FindCfgByKey(ResID)
    if not Cfg then
        return
    end
    
    local ItemID = Cfg.ItemID
    local LeftTime = (Cfg.FuncParam[1] or 0) - EatedTimes
    local Name = ItemCfg:GetItemName(ItemID)

    if LeftTime > 0 then
        MsgTipsUtil.ShowTips(string.format(HouseLocalDef.FurnitureInteractionFood.Tips1, Name))
    elseif LeftTime == 0 then
        MsgTipsUtil.ShowTips(string.format(HouseLocalDef.FurnitureInteractionFood.Tips2, Name))
    else
        MsgTipsUtil.ShowTips(string.format(HouseLocalDef.FurnitureInteractionFood.Tips3, Name))
    end
end

function FurnitureInteractionMgr:OnGameEventFurnitureDataUpdate(MsgBody)
    if not MsgBody then
        return
    end

    local FootEatBc = MsgBody.FootEatBc
    if not FootEatBc then
        return
    end

    local FurnitureID = FootEatBc.FurnitureID
    local FurnitureInfo = _G.HousingMgr:GetFurnitureInfo(FurnitureID)
    local TimelineState = self:GetFurnitureTimelineState(FurnitureInfo)

    local FixIndex = _G.HousingMgr:GetFurnitureObjectIndex(FurnitureID) - 1
    _G.HousingMgr:UpdateFurnitureTimelineState(FixIndex, TimelineState)
end

function FurnitureInteractionMgr:RspFurnitureDisplayEffectsBc(MsgBody)
    if not MsgBody then
        return
    end

    local DisplayEffectsBc = MsgBody.DisplayEffectsBc
    if not DisplayEffectsBc then
        return
    end

    local FixIndex = _G.HousingMgr:GetFurnitureObjectIndex(DisplayEffectsBc.FurnitureID) - 1
    _G.HousingMgr:UpdateFurnitureTimelineState(FixIndex, SharedGroupTimelineState.STATE_1)
end

function FurnitureInteractionMgr:RspFurnitureChangeStatusBc(MsgBody)
    if not MsgBody then
        return
    end

    local ChangeStatusBc = MsgBody.ChangeStatusBc
    if not ChangeStatusBc then
        return
    end

    local FixIndex = _G.HousingMgr:GetFurnitureObjectIndex(ChangeStatusBc.FurnitureID) - 1
    _G.HousingMgr:UpdateFurnitureTimelineState(FixIndex, ChangeStatusBc.Status)
end

