---家具交互统一入口
function FurnitureInteractionMgr:FurnitureInteractionByEntityID(EntityID)
    local FurnitureInfo = _G.HousingMgr:GetFurnitureInfoByEObyEntityID(EntityID)
    if not FurnitureInfo then
        return
    end

    local ResID = FurnitureInfo.Key or 0
    local Cfg = HousingFurnitureCfg:FindCfgByKey(ResID)
    if not Cfg then
        return
    end

    if Cfg.Function == ProtoRes.HouseFurnitureFunction.HouseFurnitureFunction_Food then --食物
        if FurnitureInfo and FurnitureInfo.Attr and FurnitureInfo.Attr.Food then
            local TotalTimes = 0
            if Cfg and Cfg.FuncParam and Cfg.FuncParam[1] then
                TotalTimes = Cfg.FuncParam[1]
            end
            local EatTimes = FurnitureInfo.Attr.Food.EatedTimes or 0
            local LeftTime = TotalTimes - EatTimes
            self:ShowFurnitureFoodUI(FurnitureInfo.GID, Cfg.ItemID or 0, LeftTime)
        end
    elseif Cfg.Function == ProtoRes.HouseFurnitureFunction.HouseFurnitureFunction_Effects then
        self:ReqDisplayEffects(FurnitureInfo.GID)
    elseif Cfg.Function == ProtoRes.HouseFurnitureFunction.HouseFurnitureFunction_Status then
        local NextStatus = SharedGroupTimelineState.STATE_1
        if FurnitureInfo.Attr and FurnitureInfo.Attr.Status then
            if FurnitureInfo.Attr.Status.CurStatus == SharedGroupTimelineState.STATE_0 then
                NextStatus = SharedGroupTimelineState.STATE_1
            else
                NextStatus = SharedGroupTimelineState.STATE_0
            end
        end
        self:ReqChangeStatus(FurnitureInfo.GID, NextStatus)
    end
end

function FurnitureInteractionMgr:ShowFurnitureFoodUI(GID, InItemID, InLeftTime)
    _G.UIViewMgr:ShowView(_G.UIViewID.HouseThingWinView, {
        ViewType = ProtoRes.HouseFurnitureFunction.HouseFurnitureFunction_Food,
        GID = GID,
        ItemID = InItemID,
        LeftTime = InLeftTime,
    })
end

---获取家具对应的TimelinState
---@param FurnitureInfo table
---@return number
function FurnitureInteractionMgr:GetFurnitureTimelineState(FurnitureInfo)
    if not FurnitureInfo then
        return SharedGroupTimelineState.STATE_0
    end
    
    local ResID = FurnitureInfo.Key or 0
    local Cfg = HousingFurnitureCfg:FindCfgByKey(ResID)
    if not Cfg then
        return SharedGroupTimelineState.STATE_0
    end

    if Cfg.Function == ProtoRes.HouseFurnitureFunction.HouseFurnitureFunction_Food then --食物
        if FurnitureInfo.Attr and FurnitureInfo.Attr.Food then
            local LeftTime = (Cfg.FuncParam[1] or 0) - (FurnitureInfo.Attr.Food.EatedTimes or 0)
            if LeftTime <= 0 then
                return SharedGroupTimelineState.STATE_1
            end
        end
    end

    return SharedGroupTimelineState.STATE_0
end

return FurnitureInteractionMgr